<?php require 'includes/auth.php';require_role('buyer');$s=db()->prepare('SELECT * FROM orders WHERE buyer_id=? ORDER BY created_at DESC');$s->execute([user()['id']]);$orders=$s->fetchAll();$pageTitle='My orders';require 'includes/header.php';?><div class="page-title"><p class="eyebrow">PURCHASE HISTORY</p><h1>My orders</h1></div><?php if($orders):?><div class="table-wrap"><table><thead><tr><th>Order</th><th>Placed</th><th>Fulfillment</th><th>Payment</th><th>Status</th><th>Total</th><th></th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=e($o['order_number'])?></td><td><?=date('d M Y',strtotime($o['created_at']))?></td><td><?=e(ucfirst($o['delivery_type']))?></td><td><?=e($o['payment_method'])?><br><span class="badge <?=e($o['payment_status'])?>"><?=e(ucfirst($o['payment_status']))?></span></td><td><span class="badge <?=status_class($o['status'])?>"><?=e($o['status'])?></span></td><td>₹<?=number_format($o['total'],2)?></td><td><a href="order-details.php?id=<?=$o['id']?>">View →</a></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty"><h2>No orders yet.</h2><a class="button" href="products.php">Shop fresh fish</a></div><?php endif;require 'includes/footer.php'; ?>
